attributes.onChange:
{(e) =>
          void configure({
            provider: e.target.value as VoiceSettings["provider"],
          })
        }

attributes.onClick:
{() => {
            const value = key;
            setKey("");
            setConsent(false);
            void perform(
              window.jarvis!.eleven({ operation: "set", key: value }),
            );
          }}

{() => {
                setConsent(false);
                void perform(
                  window.jarvis!.eleven({
                    operation: "speak",
                    voice_id: voice,
                    consent: true,
                  }),
                );
              }}

{() => {
                setConsent(false);
                void perform(window.jarvis!.eleven({
                    operation: "select",
                    voice_id: voice,
                    consent: true,
                  }));
              }}

{() => {
              reset();
              void perform(
                window.jarvis!.memory({ operation: "delete", previous: entry }),
              );
            }}

{() => {
            reset();
            const hint = { kind, label, value };
            const updated = Math.floor(Date.now() / 1000);
            void perform(
              window.jarvis!.memory(
                temporary
                  ? { operation: "session_add", hint }
                  : {
                      operation: "save",
                      entry: {
                        ...hint,
                        id:
                          previous?.id ||
                          crypto.randomUUID().replaceAll("-", ""),
                        updated,
                        expires: updated + 30 * 86400,
                      },
                      previous,
                    },
              ),
            );
            setPrevious(null);
            setLabel("");
            setValue("");
          }}

{() => {
              reset();
              void perform(
                window.jarvis!.memory({ operation: "session_delete", hint }),
              );
            }}

{() => {
            setConsent(false);
            void mail("connect", { client_id: client, consent: true });
          }}

attributes.onChange:
{(e) => {
              if (e.target.value)
                void mail("load_draft", { draft_id: e.target.value });
              e.target.value = "";
            }}

attributes.onClick:
{() =>
              void mail(op, {
                message: {
                  to: addresses(to),
                  cc: addresses(cc),
                  bcc: addresses(bcc),
                  subject,
                  body,
                  attachments: draftAttachments || state.attachments,
                },
              })
            }

{async () => {
                setPending(true); setError("");
                try {
                  const next = await window.jarvis!.workspaceBrowser(draft.browser_mode === "live"
                    ? "live" : "authenticated_workspace"); apply(next);
                  if (next.workspace) { setSaved(next.workspace); setDraft(structuredClone(next.workspace.profile)); }
                }
                catch (error) { setError(readableError(error)); }
                finally { setPending(false); }
              }}

attributes.onKeyDown:
{(event) => {
                        if (
                          (event.ctrlKey || event.metaKey) &&
                          event.key === "Enter"
                        ) {
                          event.preventDefault();
                          void submit();
                        }
                      }}
